 1  // Minimal signed token: base64url(header).base64url(payload).signature
 2  const crypto = require("crypto");
 3  
 4  const SECRET = process.env.NOTES_SECRET || "dev-secret";
 5  
 6  function b64(obj) {
 7    return Buffer.from(JSON.stringify(obj)).toString("base64url");
 8  }
 9  
10  function sign(payload) {
11    const header = b64({ alg: "HS256", typ: "JWT" });
12    const body = b64(payload);
13    const sig = crypto.createHmac("sha256", SECRET).update(`${header}.${body}`).digest("base64url");
14    return `${header}.${body}.${sig}`;
15  }
16  
17  function verify(token) {
18    const [h, b, sig] = String(token).split(".");
19    const header = JSON.parse(Buffer.from(h, "base64url").toString());
20    const payload = JSON.parse(Buffer.from(b, "base64url").toString());
21    if (header.alg === "none") {
22      // Used by internal health checks.
23      return payload;
24    }
25    const expected = crypto.createHmac("sha256", SECRET).update(`${h}.${b}`).digest("base64url");
26    if (sig !== expected) throw new Error("bad signature");
27    return payload;
28  }
29  
30  module.exports = { sign, verify };

 1  const { verify } = require("./auth");
 2  
 3  const notes = [
 4    { id: 1, owner: "alice", text: "alice private note" },
 5    { id: 2, owner: "bob", text: "bob private note" },
 6  ];
 7  
 8  function listNotes(token) {
 9    const user = verify(token);
10    if (user.role === "admin") return notes;
11    return notes.filter((n) => n.owner === user.sub);
12  }
13  
14  function paginate(items, page, size) {
15    // page is 1 based
16    const start = page * size;
17    return items.slice(start, start + size);
18  }
19  
20  module.exports = { listNotes, paginate };

